evaluation/judge_metadata.py:
"""Judge prompt provenance and provider-reported token/cost accounting, not quality labels."""

import hashlib
import importlib.metadata
import math
import os


def prompt_manifest(metrics) -> dict:
    prompts = {}
    for metric in metrics:
        for name, prompt in metric.get_prompts().items():
            text = prompt.to_string()
            prompts[f"{metric.name}/{name}"] = {"sha256": hashlib.sha256(text.encode()).hexdigest(), "template": text}
    return prompts


def judge_accounting(result) -> dict:
    usage = result.total_tokens()
    values = usage if isinstance(usage, list) else [usage]
    inputs = sum(u.input_tokens for u in values)
    outputs = sum(u.output_tokens for u in values)
    prices = [os.getenv("JUDGE_INPUT_USD_PER_MILLION"), os.getenv("JUDGE_OUTPUT_USD_PER_MILLION")]
    dollars = None
    if all(p is not None for p in prices):
        rates = [float(p) for p in prices if p is not None]
        if any(not math.isfinite(p) or p < 0 for p in rates):
            raise ValueError("Judge prices must be finite nonnegative USD per million tokens")
        if inputs + outputs > 0:
            dollars = (inputs * rates[0] + outputs * rates[1]) / 1_000_000
    return {
        "provider_reported_input_tokens": inputs if inputs + outputs > 0 else None,
        "provider_reported_output_tokens": outputs if inputs + outputs > 0 else None,
        "estimated_judge_usd": dollars,
        "price_usd_per_million": prices,
        "scope": "RAGAS judge calls with reported token usage only; excludes pipeline calls and unreported retries",
        "usage_status": "observed" if inputs + outputs > 0 else "unavailable; not zero-cost evidence",
    }


def judge_identity() -> dict:
    return {
        "model": os.getenv("LLM_MODEL", "gpt-4o-mini"),
        "version": os.getenv("JUDGE_MODEL_VERSION") or "unspecified provider alias; not immutable",
        "ragas_version": importlib.metadata.version("ragas"),
        "temperature": 0.0,
        "human_label_validation": "not measured; no independently human-labeled answer subset available",
        "judge_disagreement": None,
        "false_positive_rate": None,
        "limitations": "LLM judgment is nondeterministic and is not objective ground truth or answer correctness",
    }

evaluation/ranking.py:
"""Versioned ranking semantics. See docs/EXPERIMENTS.md for exact conventions."""

from __future__ import annotations

import math
from collections.abc import Mapping, Sequence

METRIC_VERSION = "ranking-v2-exp2-fixed-k"
METRICS = ("recall", "precision", "mrr", "ndcg", "hit_rate")


def rank_scores(scores: Mapping[str, float]) -> list[str]:
    """Descending finite score, then ascending document ID; no tie averaging."""
    if any(not math.isfinite(v) for v in scores.values()):
        raise ValueError("Ranking scores must be finite")
    return sorted(scores, key=lambda doc: (-scores[doc], doc))


def evaluate_ranking(
    ranked: Sequence[str], qrels: Mapping[str, int], k: int, no_positive: str = "exclude"
) -> dict[str, float] | None:
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError("K must be a positive integer")
    if no_positive not in {"exclude", "zero"}:
        raise ValueError("Unknown no-positive policy")
    if not qrels:
        raise ValueError("Missing relevance judgments")
    if any(isinstance(g, bool) or not isinstance(g, int) or not 0 <= g <= 30 for g in qrels.values()):
        raise ValueError("Judgment grades must be integers in [0, 30]")
    if len(ranked) != len(set(ranked)):
        raise ValueError("Duplicate retrieved document IDs")
    positive = sum(g > 0 for g in qrels.values())
    if not positive:
        return None if no_positive == "exclude" else dict.fromkeys(METRICS, 0.0)
    grades = [qrels.get(doc, 0) for doc in ranked[:k]]
    hits = [g > 0 for g in grades]
    dcg = sum((2**grade - 1) / math.log2(i + 2) for i, grade in enumerate(grades))
    ideal = sorted(qrels.values(), reverse=True)[:k]
    idcg = sum((2**grade - 1) / math.log2(i + 2) for i, grade in enumerate(ideal))
    return {
        "recall": sum(hits) / positive,
        "precision": sum(hits) / k,
        "mrr": next((1 / (i + 1) for i, hit in enumerate(hits) if hit), 0.0),
        "ndcg": dcg / idcg,
        "hit_rate": float(any(hits)),
    }

evaluation/retrieval_data.py:
"""Strict, hashed BEIR-compatible corpus/query/qrels manifests."""

from __future__ import annotations

import csv
import hashlib
import json
from dataclasses import dataclass
from pathlib import Path


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _records(path: Path, title: bool = False) -> dict[str, str]:
    result = {}
    for number, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        if not line.strip():
            continue
        row = json.loads(line)
        identifier, text = row.get("_id"), row.get("text")
        if not isinstance(identifier, str) or not identifier.strip() or not isinstance(text, str) or not text.strip():
            raise ValueError(f"Invalid identifier/text in {path.name}:{number}")
        if identifier in result:
            raise ValueError(f"Duplicate identifier in {path.name}:{number}")
        heading = row.get("title", "")
        if not isinstance(heading, str):
            raise ValueError("Title must be a string")
        result[identifier] = f"{heading.strip()} {text.strip()}".strip() if title else text.strip()
    if not result:
        raise ValueError(f"Empty data file: {path.name}")
    return result


@dataclass(frozen=True)
class RetrievalDataset:
    metadata: dict
    corpus: dict[str, str]
    queries: dict[str, str]
    qrels: dict[str, dict[str, int]]

    def identity(self) -> dict:
        return {
            **self.metadata,
            "corpus_count": len(self.corpus),
            "query_count": len(self.queries),
            "qrel_count": sum(map(len, self.qrels.values())),
            "positive_qrel_count": sum(g > 0 for judgments in self.qrels.values() for g in judgments.values()),
            "queries_without_positives": sum(not any(g > 0 for g in q.values()) for q in self.qrels.values()),
        }


def load_dataset(manifest_path: Path) -> RetrievalDataset:
    meta = json.loads(manifest_path.read_text(encoding="utf-8"))
    required = {"schema_version", "id", "version", "split", "role", "origin", "license", "files"}
    if required - set(meta) or meta["schema_version"] != 1:
        raise ValueError("Invalid dataset manifest/schema version")
    if any(not isinstance(meta[key], str) or not meta[key].strip() for key in required - {"files", "schema_version"}):
        raise ValueError("Dataset identity fields must be nonempty strings")
    if meta["role"] not in {"benchmark", "development", "regression"}:
        raise ValueError("Invalid dataset role")
    if meta["split"] == "train" and meta["role"] != "development":
        raise ValueError("Training split cannot be a benchmark")
    if meta["split"] == "test" and meta["role"] != "benchmark":
        raise ValueError("Test split must be marked benchmark")
    if set(meta["files"]) != {"corpus", "queries", "qrels"}:
        raise ValueError("Manifest must specify corpus, queries and qrels")
    paths = {}
    for kind, spec in meta["files"].items():
        path = manifest_path.parent / spec["path"]
        if sha256(path) != spec["sha256"]:
            raise ValueError(f"Dataset checksum/version mismatch: {kind}")
        paths[kind] = path
    corpus = _records(paths["corpus"], title=True)
    queries = _records(paths["queries"])
    qrels: dict[str, dict[str, int]] = {}
    with paths["qrels"].open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        if reader.fieldnames != ["query-id", "corpus-id", "score"]:
            raise ValueError("Invalid qrels header")
        for row in reader:
            qid, doc = row["query-id"], row["corpus-id"]
            if qid not in queries or doc not in corpus:
                raise ValueError("Qrel references missing query or document ID")
            try:
                grade = int(row["score"])
            except (ValueError, TypeError) as exc:
                raise ValueError("Invalid relevance grade") from exc
            if str(grade) != row["score"] or not 0 <= grade <= 30:
                raise ValueError("Relevance grade must be a canonical integer in [0, 30]")
            if doc in qrels.setdefault(qid, {}):
                raise ValueError("Duplicate relevance judgment")
            qrels[qid][doc] = grade
    if not qrels:
        raise ValueError("Empty qrels")
    # BEIR queries.jsonl can contain multiple splits; only qrels-listed queries are evaluated.
    selected = {qid: queries[qid] for qid in sorted(qrels)}
    for field, actual in (
        ("corpus_count", len(corpus)),
        ("query_count", len(selected)),
        ("qrel_count", sum(map(len, qrels.values()))),
    ):
        if field in meta and meta[field] != actual:
            raise ValueError(f"Dataset count/version mismatch: {field}")
    return RetrievalDataset(meta, dict(sorted(corpus.items())), selected, qrels)

evaluation/retrieval_gate.py:
"""Versioned deterministic fixture gate; no latency thresholds on shared CI workers."""

import argparse
import json
import math
from pathlib import Path


def conditions(report: dict) -> dict:
    return {"metric_version": report["metric_version"], "config": report["config"], "dataset": report["dataset"]}


def evaluate_gate(report: dict, baseline: dict) -> list[str]:
    if report.get("status") != "COMPLETE" or baseline.get("schema_version") != 1:
        raise ValueError("Incomplete report or unsupported baseline")
    if conditions(report) != baseline["conditions"]:
        raise ValueError("Baseline dataset/configuration/metric definitions differ")
    results = {r["id"]: r for r in report["results"]}
    if len(results) != len(report["results"]) or set(results) != set(baseline["expected"]):
        raise ValueError("Missing, duplicate or unexpected configurations")
    failures = []
    for name, expected in baseline["expected"].items():
        current = results[name]
        for key in ("corpus_count", "query_count", "scored_query_count", "corpus_ids_sha256", "query_ids_sha256"):
            if current[key] != expected[key]:
                raise ValueError(f"Benchmark conditions differ: {name}/{key}")
        if set(current["quality"]) != set(expected["quality"]):
            raise ValueError("Metric keys differ")
        for metric, target in expected["quality"].items():
            value = current["quality"][metric]
            if not math.isfinite(value) or value < target - 1e-12:
                failures.append(f"{name} {metric}: {value} < {target}")
    return failures


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--report", type=Path, required=True)
    parser.add_argument("--baseline", type=Path, required=True)
    args = parser.parse_args()
    failures = evaluate_gate(json.loads(args.report.read_text()), json.loads(args.baseline.read_text()))
    if failures:
        raise SystemExit("\n".join(failures))
    print("PASS: versioned deterministic retrieval quality baseline")


if __name__ == "__main__":
    main()

telemetry.py:
"""Cloud-native observability helpers for traces, metrics, logs, and correlation IDs."""

from __future__ import annotations

import contextvars
import json
import logging
import time
import uuid
from contextlib import contextmanager
from dataclasses import dataclass
from typing import Any

from config import TelemetryConfig

try:
    from opentelemetry import metrics, trace
    from opentelemetry.sdk.resources import Resource
    from opentelemetry.sdk.trace import TracerProvider
    from opentelemetry.sdk.trace.export import BatchSpanProcessor, ConsoleSpanExporter
    from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter
    from opentelemetry.sdk.metrics import MeterProvider
    from opentelemetry.sdk.metrics.export import ConsoleMetricExporter, PeriodicExportingMetricReader
    from opentelemetry.exporter.otlp.proto.http.metric_exporter import OTLPMetricExporter

    OTEL_AVAILABLE = True
except Exception:  # pragma: no cover - optional dependency path
    metrics = None  # type: ignore[assignment]
    trace = None  # type: ignore[assignment]
    Resource = None  # type: ignore[assignment,misc]
    TracerProvider = None  # type: ignore[assignment,misc]
    BatchSpanProcessor = None  # type: ignore[assignment,misc]
    ConsoleSpanExporter = None  # type: ignore[assignment,misc]
    OTLPSpanExporter = None  # type: ignore[assignment,misc]
    MeterProvider = None  # type: ignore[assignment,misc]
    ConsoleMetricExporter = None  # type: ignore[assignment,misc]
    PeriodicExportingMetricReader = None  # type: ignore[assignment,misc]
    OTLPMetricExporter = None  # type: ignore[assignment,misc]
    OTEL_AVAILABLE = False


_correlation_id_var: contextvars.ContextVar[str | None] = contextvars.ContextVar("correlation_id", default=None)
_tracer_provider_configured = False
_meter_provider_configured = False
_logging_configured = False
_metric_instruments: dict[tuple[str, str], Any] = {}


@dataclass(frozen=True)
class ExporterSelection:
    exporter: str
    endpoint: str | None


class JsonLogFormatter(logging.Formatter):
    """Small structured-log formatter with trace/span/correlation enrichment."""

    def format(self, record: logging.LogRecord) -> str:
        payload = {
            "timestamp": self.formatTime(record, "%Y-%m-%dT%H:%M:%S%z"),
            "level": record.levelname,
            "logger": record.name,
            "message": record.getMessage(),
            "correlation_id": get_correlation_id(),
        }

        span_context = get_current_span_context()
        if span_context:
            payload["trace_id"] = span_context["trace_id"]
            payload["span_id"] = span_context["span_id"]

        if record.exc_info:
            payload["exception"] = self.formatException(record.exc_info)

        return json.dumps({k: v for k, v in payload.items() if v is not None}, ensure_ascii=False)


def set_correlation_id(value: str) -> None:
    _correlation_id_var.set(value)


def reset_correlation_id() -> None:
    _correlation_id_var.set(None)


def get_correlation_id() -> str | None:
    return _correlation_id_var.get()


def get_or_create_correlation_id() -> str:
    existing = get_correlation_id()
    if existing:
        return existing
    created = str(uuid.uuid4())
    set_correlation_id(created)
    return created


def resolve_exporter_config(config: TelemetryConfig) -> ExporterSelection:
    exporter = (config.telemetry_exporter or "console").strip().lower()
    if exporter not in {"console", "otlp", "none"}:
        exporter = "console"
    endpoint = config.telemetry_otlp_endpoint if exporter == "otlp" else None
    return ExporterSelection(exporter=exporter, endpoint=endpoint)


def configure_observability(config: TelemetryConfig) -> None:
    """Configure tracing, metrics, and structured logs once per process."""

    if not config.telemetry_enabled:
        return

    configure_structured_logging(config)
    configure_tracer_provider(config)
    configure_meter_provider(config)


def configure_structured_logging(config: TelemetryConfig) -> None:
    """Enable JSON logs when configured. Existing handlers are reused."""

    global _logging_configured
    if _logging_configured or not config.structured_logs_enabled:
        return

    root = logging.getLogger()
    if not root.handlers:
        root.addHandler(logging.StreamHandler())
    for handler in root.handlers:
        handler.setFormatter(JsonLogFormatter())
    root.setLevel(getattr(logging, config.log_level.upper(), logging.INFO))
    _logging_configured = True


def configure_tracer_provider(config: TelemetryConfig):
    """Configure OpenTelemetry traces with low-overhead batch exporting."""

    global _tracer_provider_configured
    if not config.telemetry_enabled or not OTEL_AVAILABLE or trace is None:
        return None

    if _tracer_provider_configured:
        return trace.get_tracer_provider()

    existing_provider = trace.get_tracer_provider()
    if isinstance(existing_provider, TracerProvider):
        _tracer_provider_configured = True
        return existing_provider

    selection = resolve_exporter_config(config)
    if selection.exporter == "none":
        return None

    provider = TracerProvider(resource=_resource(config))
    exporter = _build_span_exporter(selection)
    provider.add_span_processor(BatchSpanProcessor(exporter))
    trace.set_tracer_provider(provider)
    _tracer_provider_configured = True
    return provider


def configure_meter_provider(config: TelemetryConfig):
    """Configure OpenTelemetry metrics with periodic export."""

    global _meter_provider_configured
    if not config.telemetry_enabled or not config.metrics_enabled or not OTEL_AVAILABLE or metrics is None:
        return None

    if _meter_provider_configured:
        return metrics.get_meter_provider()

    selection = resolve_exporter_config(config)
    if selection.exporter == "none":
        return None

    exporter = _build_metric_exporter(selection)
    reader = PeriodicExportingMetricReader(exporter, export_interval_millis=config.metric_export_interval_ms)
    provider = MeterProvider(resource=_resource(config), metric_readers=[reader])
    metrics.set_meter_provider(provider)
    _meter_provider_configured = True
    return provider


def get_tracer(name: str = "rag-pipeline"):
    if not OTEL_AVAILABLE or trace is None:
        return None
    return trace.get_tracer(name)


def get_meter(name: str = "rag-pipeline"):
    if not OTEL_AVAILABLE or metrics is None:
        return None
    return metrics.get_meter(name)


def get_current_span_context() -> dict[str, str] | None:
    if not OTEL_AVAILABLE or trace is None:
        return None
    span = trace.get_current_span()
    if not span:
        return None
    context = span.get_span_context()
    if not context or not context.is_valid:
        return None
    return {
        "trace_id": f"{context.trace_id:032x}",
        "span_id": f"{context.span_id:016x}",
    }


@contextmanager
def start_span(name: str, attributes: dict[str, Any] | None = None, tracer_name: str = "rag-pipeline"):
    tracer = get_tracer(tracer_name)
    if not tracer:
        yield None
        return
    # Exception messages can contain prompts/documents. Export only the exception type.
    with tracer.start_as_current_span(name, record_exception=False, set_status_on_exception=False) as span:
        if attributes:
            set_span_attributes(span, attributes)
        try:
            yield span
        except Exception as exc:
            if trace is not None:
                span.set_status(trace.Status(trace.StatusCode.ERROR, type(exc).__name__))
            span.add_event("exception", {"exception.type": type(exc).__name__})
            raise


def set_span_attributes(span, attributes: dict[str, Any]) -> None:
    if not span:
        return
    for key, value in attributes.items():
        if value is not None:
            span.set_attribute(key, value)


def record_histogram(name: str, value: float, attributes: dict[str, Any] | None = None, unit: str = "1") -> None:
    instrument = _get_metric_instrument("histogram", name, unit)
    if instrument is not None:
        instrument.record(float(value), attributes or {})


def add_counter(name: str, value: int | float = 1, attributes: dict[str, Any] | None = None, unit: str = "1") -> None:
    instrument = _get_metric_instrument("counter", name, unit)
    if instrument is not None:
        instrument.add(value, attributes or {})


def observe_duration(name: str, start_time: float, attributes: dict[str, Any] | None = None) -> float:
    elapsed_ms = (time.perf_counter() - start_time) * 1000
    record_histogram(name, elapsed_ms, attributes=attributes)
    return elapsed_ms


def span_context_or_null(name: str, attributes: dict[str, Any] | None = None, tracer_name: str = "rag-pipeline"):
    # Use the same attribute-aware context manager as explicit stage spans.
    # Previously attributes passed by pipeline callers were silently discarded.
    return start_span(name, attributes, tracer_name)


def _get_metric_instrument(kind: str, name: str, unit: str):
    meter = get_meter("rag.metrics")
    if not meter:
        return None

    key = (kind, name)
    if key in _metric_instruments:
        return _metric_instruments[key]

    if kind == "histogram":
        instrument = meter.create_histogram(name, unit=unit)
    elif kind == "counter":
        instrument = meter.create_counter(name, unit=unit)
    else:
        return None

    _metric_instruments[key] = instrument
    return instrument


def _resource(config: TelemetryConfig):
    attrs = {
        "service.name": config.telemetry_service_name,
        "service.version": config.service_version,
        "deployment.environment": config.environment,
    }
    return Resource.create(attrs)


def _build_span_exporter(selection: ExporterSelection):
    if selection.exporter == "otlp" and selection.endpoint:
        return OTLPSpanExporter(endpoint=_otlp_endpoint(selection.endpoint, "traces"))
    return ConsoleSpanExporter()


def _build_metric_exporter(selection: ExporterSelection):
    if selection.exporter == "otlp" and selection.endpoint:
        return OTLPMetricExporter(endpoint=_otlp_endpoint(selection.endpoint, "metrics"))
    return ConsoleMetricExporter()


def _otlp_endpoint(base: str, signal: str) -> str:
    base = base.rstrip("/")
    if base.endswith(f"/v1/{signal}"):
        return base
    if base.endswith("/v1/traces") or base.endswith("/v1/metrics"):
        return f"{base.rsplit('/v1/', 1)[0]}/v1/{signal}"
    return f"{base}/v1/{signal}"
